import type { WordbookExample } from './wordbookExample';
import type { WordbookPartOfSpeech } from './wordbookPartOfSpeech';

/**
 * The mục từ a card's back is drawn from — R-15's "Mặt sau" in full,
 * which R-15 delegates to `R-17` and R-33 restates for a second corpus.
 *
 * **Singular where `wordbookSources` is a list**, and the two are not one
 * thing at two cardinalities. `wordbookSources` answers "which papers
 * record this card" and TCCN-503-3 makes that a list. This answers "what
 * does the back SAY", and there can only be one answer: a back showing
 * two readings, two word classes and four example sentences is not a flip
 * card. The two are independent — a card may carry this and an empty
 * `wordbookSources`, because a lookup is not a save.
 *
 * Absent, not empty, when nothing in the bank describes this word. R-15's
 * back is seven rows and `back` is one string; a card that has only that
 * string renders one line rather than six empty ones — TCCN-109-5's rule
 * applied to the back instead of to the source row. TCCN-116-8 still
 * requires such a card to flip.
 *
 * ⚠ `back` may already hold the same contextual meaning: the wordbook
 * screen writes it there when the learner saves (`SaveControl`). A client
 * must not print it twice.
 */
export interface MyCardWordbookEntry {
  entryId: string;
  examId: string;
  examCode: string;
  /**
     * The paper this back is quoted from, carried so the client can say
     * so — "theo bảng từ vựng đề TOPIK-91" — and link to it. It is also
     * what makes `contextMeaningVi` readable at all: a contextual meaning
     * with no paper on it is a claim with no subject.
     */
  examTitle: string;
  /** Cách đọc, in Latin script — R-15's first row of the back. */
  readingLatin: string;
  partOfSpeech: WordbookPartOfSpeech;
  /**
     * Nghĩa chung. R-33: "xem thêm được, không thay cho nghĩa trong ngữ
     * cảnh" — shown second, and never copied into the field below.
     */
  meaningVi: string;
  /**
     * Nghĩa trong ngữ cảnh — "nghĩa ở chính ngữ liệu sinh ra thẻ này".
     *
     * **Present ⟺ this paper is the card's own ngữ liệu.** That is the
     * invariant a client may lean on, and its absence is the correctness
     * core of this field: it is filled only when the paper is provably
     * the one that made the card (same create() transaction, and for a
     * card from a wrong answer, the same paper as that question).
     *
     * A contextual meaning borrowed from an unrelated paper would be the
     * same word with a different meaning presented as this card's own,
     * with nothing on screen saying so. Absent is a designed state here
     * exactly as it is for `source` (TCCN-109-5); it is never filled by
     * copying `meaningVi`, which R-33 forbids by name.
     */
  contextMeaningVi?: string;
  /**
     * Exactly two, in order — R-33 requires two, "không một, không ba".
     * Never absent, so a client has one branch.
     */
  examples: WordbookExample[];
  /**
     * Absolute against the public bucket when one is configured, and
     * root-relative on this API otherwise — the same convention and the
     * same helper as `WordbookItem.audioUrl`, and clients tell the two
     * apart by the leading slash.
     *
     * R-15: "Nghe lại không giới hạn". The absolute form satisfies that
     * with no server in the loop at all. Note the root-relative fallback
     * is served under `wordbook:read:own`, so revoking that permission
     * would 403 a card's audio while the rest of its back still renders.
     */
  audioUrl: string;
}
